from pathlib import Path
import sys
sys.path.insert(0,str(Path(__file__).resolve().parent.parent))
from rendu import outils

B,p,c,h,w,table,liste,save=outils(1,1)
t=h('1.a — Une douleur régionale reliée à un point gâchette musculaire')
t+=p('La DGN, dans sa recommandation révisée en 2025, décrit le syndrome douloureux myofascial comme un diagnostic clinique fondé sur des points gâchettes ; elle associe une sensibilité locale, une bande musculaire tendue, une secousse locale et une douleur référée.','p83-myofascial-fibro','dgn83-bib')
t+=p('La douleur intéresse une région et peut provenir de plusieurs muscles de cette même région. Ainsi, le territoire où le patient ressent la douleur et le lieu de la structure musculaire qui la reproduit peuvent être différents.','c83-1','c83-9')
a=w('Point gâchette, bande tendue et secousse locale',[
('La bande tendue est un faisceau musculaire palpable, plus ferme et raccourci que les tissus voisins. Le point gâchette correspond à une zone hypersensible située dans cette bande, et non à toute la surface douloureuse.',['p83-myofascial-fibro','c83-7']),
('La stimulation du point provoque une douleur locale et peut déclencher une douleur ressentie à distance. Cette reproduction relie donc l’observation de l’examinateur à l’expérience douloureuse rapportée par le patient.',['c83-1','c83-7']),
('La secousse locale est une contraction brève du faisceau stimulé ; elle se distingue du sursaut global du patient à cause de la douleur. Les deux réponses sont observées séparément pendant la palpation.',['c83-7','iasp83-criteres'])])
t+=p('Le clinicien précise les termes '+a+' avant de cartographier le symptôme ; un point sensible isolé et une douleur régionale ne décrivent donc pas encore la même observation.','p83-myofascial-fibro','iasp83-criteres')
t+=h('1.b — Le caractère actif dépend de la reconnaissance des symptômes')
t+=p('Un point actif contribue à la plainte clinique : sa stimulation reproduit un symptôme que le patient reconnaît comme familier. Cette reconnaissance peut porter sur toute la plainte ou sur une partie de celle-ci.','eu83-actif','eu83-latent')
t+=p('Un point latent reste silencieux quant à la douleur spontanée et devient douloureux à la palpation. Toutefois, sa stimulation peut aussi produire une sensation référée ; la présence de cette sensation ne suffit donc pas à qualifier le point d’actif.','eu83-latent','c83-8')
a=w('Actif, latent et sujet asymptomatique',[
('La classification actif ou latent concerne le lien entre le point palpé et la plainte spontanée. Le clinicien demande donc au patient de comparer la sensation reproduite à son problème habituel.',['eu83-actif','eu83-latent']),
('Des points latents ont été décrits chez des personnes asymptomatiques. Leur découverte doit ainsi être replacée dans l’anamnèse et la fonction, plutôt que transformer toute sensibilité provoquée en maladie.',['eu83-phenotypes']),
('La notion de sensation référée inclut la douleur mais aussi des sensations telles que picotements ou brûlure. Ces descriptions participent à la caractérisation clinique sans établir, seules, une lésion nerveuse.',['eu83-latent','c83-9'])])
t+=p('La distinction '+a+' évite de traiter un résultat de palpation sans relation avec les symptômes. Elle permet aussi de distinguer une observation périphérique d’un diagnostic portant sur toute la personne.','eu83-phenotypes','barbero83-resume')
t+=h('1.c — Primaire, secondaire et chronique désignent des dimensions différentes')
t+=p('La DGN distingue une forme primaire, associée à la surcharge musculaire, et une forme secondaire dont les mécanismes sont moins précisément établis. Une surcharge décrite comme un possible microtraumatisme reste donc une explication clinique contextualisée.','p83-myofascial-fibro')
t+=p('Le syndrome peut également s’entretenir dans un contexte d’arthropathie, de douleur neuropathique, de spasticité ou de contraintes posturales. Le clinicien recherche alors le facteur associé afin de ne pas limiter la prise en charge au seul point palpable.','c83-22')
t+=p('La chronicité se juge sur la durée et le retentissement. NICE définit la douleur chronique par sa persistance ou sa récurrence au-delà de trois mois ; cette définition temporelle ne transforme pas toute douleur myofasciale en douleur chronique primaire.','nice83-definition')
t+=p('Une douleur chronique primaire peut coexister avec une cause secondaire. Dès lors, le bilan régional, l’évaluation de la fonction et les facteurs de maintien restent complémentaires plutôt que mutuellement exclusifs.','nice83-vie','nice83-evaluation')
t+=h('1.d — Les diagnostics voisins gardent leurs signes propres')
t+=p('La fibromyalgie correspond à un tableau chronique plus diffus, avec fatigue et sommeil non réparateur ; le syndrome myofascial privilégie une organisation régionale et la reproduction de symptômes à partir du muscle. Les deux situations demandent cependant une recherche des affections associées.','p83-myofascial-fibro')
t+=p('Une douleur référée musculaire peut ressembler à une radiculopathie. Toutefois, une topographie évocatrice doit être confrontée aux réflexes, à la force et à la sensibilité, puis aux examens indiqués, pour caractériser réellement une atteinte radiculaire.','c83-9','c83-30')
t+=p('Les courbatures retardées après effort et la contusion directe suivent une autre chronologie clinique. La première apparaît après l’activité, tandis que la seconde débute immédiatement après le choc et s’accompagne d’un hématome de taille variable.','p83-doms-contusion-clinique')
save(t)

B,p,c,h,w,table,liste,save=outils(1,2)
t=h('2.a — La fréquence dépend de la présentation et du lieu de soins')
t+=p('La DGN situe le syndrome myofascial comme la forme la plus fréquente des douleurs musculaires localisées. En revanche, elle situe la fibromyalgie en tête des formes généralisées : les deux qualifications concernent donc des présentations différentes.','p83-myofascial-fibro')
t+=p('L’intérêt pratique de cette distinction est de commencer par une carte anatomique de la douleur. Une plainte focale, une plainte régionale et une plainte étendue ne conduisent pas à la même hiérarchie diagnostique ni au même examen de départ.','dgn83-localisation','p83-myofascial-fibro')
t+=p('La revue suisse de Barbero et ses collègues considère les points gâchettes comme des générateurs périphériques susceptibles de participer à la douleur et à l’incapacité. Elle relie donc leur recherche à une histoire clinique attentive et à un examen manuel spécifique.','barbero83-resume')
t+=p('Les tableaux myofasciaux peuvent être rencontrés dans les douleurs cervicales mécaniques, après un coup du lapin, dans les douleurs d’épaule ou les lombalgies. Ces associations décrivent un contexte clinique ; elles ne prouvent pas que le point gâchette soit l’unique cause de chaque douleur régionale.','eu83-phenotypes','iasp83-clinique')
t+=h('2.b — Contraintes professionnelles, effort et muscles sollicités')
t+=p('La surutilisation brève, le traumatisme musculaire et le maintien d’une activité prolongée peuvent déclencher un tableau myofascial. Le niveau de contraction n’a donc pas besoin d’être maximal pour qu’une contrainte soutenue soit pertinente dans l’entretien.','c83-2','c83-17')
t+=p('Des situations de travail sur ordinateur, de pratique musicale ou de soins dentaires maintiennent certains muscles en contraction prolongée. Ainsi, l’analyse de la tâche et des possibilités de variation de posture apporte une information différente du seul intitulé professionnel.','c83-19')
t+=p('Une douleur liée à l’usage peut ensuite réduire l’utilisation du muscle atteint. Le patient décrit parfois cette réduction comme une faiblesse, tandis que les muscles voisins augmentent leur activité compensatoire et peuvent participer au maintien du tableau.','c83-15','c83-16')
t+=p('Le clinicien distingue cette limitation liée à la douleur d’une faiblesse objectivée. Une diminution de force peut aussi relever d’une arthropathie, d’un problème tendineux, d’une radiculopathie ou d’une neuropathie ; le contexte professionnel ne ferme donc pas le diagnostic.','oa82-hug-force')
t+=h('2.c — Une évolution favorable et une persistance prolongée restent deux trajectoires possibles')
a=w('Histoire naturelle et facteurs de maintien',[
('Certaines douleurs apparues après une contrainte disparaissent en quelques heures ou quelques jours, spontanément ou après correction de la cause. Cette trajectoire justifie une réévaluation de la fonction et des facteurs déclenchants.',['c83-20']),
('D’autres douleurs persistent après la résolution du problème initial ou gagnent des régions voisines. Les troubles du sommeil, le stress et les modifications de l’humeur peuvent alors accompagner la chronicisation.',['c83-20','c83-21']),
('Les facteurs mécaniques comprennent des contraintes préexistantes, des adaptations apparues à cause de la douleur et des facteurs qui continuent d’agir. L’examen recherche donc autant la situation actuelle que l’événement de départ.',['c83-22']),
('La revue européenne décrit une interaction possible entre nociception périphérique et sensibilisation centrale. Ce modèle permet d’expliquer une persistance sans réduire toute la douleur à la taille d’une lésion visible.',['eu83-nociplastic','eu83-sensibilisation'])])
t+=p('La fenêtre '+a+' distingue l’événement déclenchant de ce qui entretient la plainte. Ainsi, la consultation de suivi porte aussi sur la mobilité, les activités habituelles et les adaptations déjà tentées.','c83-20','c83-22','nice83-vie')
t+=p('Le stress lié à la douleur et à ses limitations peut contribuer à sa persistance. Il est exploré comme un facteur de maintien et de retentissement, en parallèle de l’examen musculaire et neurologique.','c83-23','nice83-vie')
t+=h('2.d — Le retentissement fonctionnel oriente la prise en charge')
t+=p('La douleur chronique peut modifier sommeil, travail, participation sociale et relations avec l’entourage. NICE recommande ainsi une appréciation centrée sur la personne, qui reconnaît également les difficultés de logement, de revenu ou d’emploi susceptibles de compliquer le parcours.','nice83-vie','nice83-evaluation')
t+=p('Les limites d’activité et les comportements de protection donnent un sens clinique au suivi. Le traitement vise donc une participation plus autonome aux activités et une meilleure gestion des symptômes, avec des moyens adaptés au contexte individuel.','eu83-multimodal','nice83-physique')
t+=p('La découverte de points latents chez des personnes sans symptômes souligne l’importance de ce retentissement. Le nombre de sites douloureux à la pression et la gêne vécue ne constituent donc pas des mesures interchangeables de maladie.','eu83-phenotypes','barbero83-resume')
save(t)

B,p,c,h,w,table,liste,save=outils(1,3)
t=h('3.a — De la contrainte musculaire au foyer périphérique sensible')
t+=p('La surcharge et la contraction prolongée constituent des circonstances de déclenchement décrites du syndrome myofascial. Toutefois, la physiopathologie du point gâchette comporte plusieurs mécanismes proposés plutôt qu’une séquence moléculaire unique démontrée chez chaque patient.','c83-17','iasp83-physio')
t+=p('La bande tendue possède une rigidité accrue et contient une zone hypersensible. Cette organisation tissulaire rend compte de la différence entre la palpation d’un faisceau ferme et la recherche du point qui reproduit les symptômes.','iasp83-physio','p83-myofascial-fibro')
a=w('Plaque motrice et sarcomère : un modèle mécanistique',[
('Des études décrivent une activité électrique spontanée au niveau des points gâchettes, attribuée notamment aux potentiels de plaque et à une libération accrue d’acétylcholine. Ces observations soutiennent un modèle de dysfonction locale, avec des résultats encore à confirmer.',['iasp83-physio']),
('La revue européenne propose que le needling puisse modifier l’activité de la plaque motrice, la longueur sarcomérique et le chevauchement actine-myosine. Ces mécanismes restent des explications proposées de l’effet, distinctes d’un critère clinique de guérison.',['eu83-modeles','eu83-mecanique']),
('La longueur et la contracture du sarcomère appartiennent à l’échelle cellulaire ; la bande tendue et la limitation du mouvement appartiennent à l’échelle tissulaire et clinique. L’interprétation relie donc les niveaux sans transformer le modèle en preuve étiologique individuelle.',['eu83-mecanique','iasp83-criteres'])])
t+=p('La fenêtre '+a+' détaille l’hypothèse de la plaque motrice. En pratique, l’examen retient surtout les manifestations accessibles : bande tendue, point hypersensible et symptômes reproduits à sa stimulation.','p83-myofascial-fibro','iasp83-criteres')
t+=h('3.b — Médiateurs locaux et sensibilisation périphérique')
t+=p('Des études comparant les zones gâchettes et les régions non gâchettes décrivent un milieu chimique modifié. Des substances telles que la substance P, certaines interleukines et le TNF participent aux modèles de sensibilisation des terminaisons nociceptives.','eu83-milieu','iasp83-physio')
t+=p('La sensibilisation périphérique signifie ici que les entrées sensorielles provenant de la région musculaire contribuent davantage à la douleur. Ainsi, une stimulation mécanique du point peut provoquer une réponse locale importante et alimenter les voies nociceptives.','eu83-milieu','iasp83-clinique')
t+=p('Les phénomènes décrits incluent une sensibilité accrue aux stimulations douloureuses et à certaines stimulations habituellement non douloureuses. Le clinicien précise donc le type de sensation provoquée plutôt que regrouper toute réaction sous une simple contracture.','iasp83-physio','c83-10')
a=w('Hyperalgie, allodynie et sensation référée',[
('L’hyperalgie correspond à une hypersensibilité envers un stimulus nociceptif, tandis que l’allodynie concerne un stimulus non nociceptif. Ces deux descriptions qualifient la relation entre le stimulus appliqué et la douleur ressentie.',['iasp83-physio']),
('La sensation référée est perçue à distance du point stimulé et peut comprendre une douleur profonde, un tiraillement, une brûlure ou des picotements. Le clinicien fait préciser son territoire et son caractère familier.',['eu83-latent','iasp83-clinique']),
('Cette topographie ne suit pas nécessairement un tronc nerveux ou une racine. L’examen neurologique conserve donc sa valeur pour distinguer une sensation référée et une atteinte nerveuse associée.',['c83-9','c83-30'])])
t+=p('La distinction '+a+' précise les signes sensoriels du syndrome. Elle explique aussi pourquoi une sensation qui s’étend dans un membre demande une confrontation au reste de l’examen.','c83-9','c83-10','c83-30')
t+=h('3.c — Moelle, tronc cérébral et persistance de la douleur')
t+=p('Les travaux expérimentaux repris dans la revue européenne soutiennent une contribution des points gâchettes à la sensibilisation périphérique et centrale. Ils impliquent des neurones de la corne dorsale et des niveaux supraspinaux, plutôt qu’un mécanisme limité au muscle.','eu83-milieu','eu83-neurophysio')
t+=p('La sensibilisation centrale correspond à une amplification de la signalisation nociceptive et à une réponse accrue des neurones centraux à leurs entrées. Ce mécanisme aide ainsi à comprendre l’hypersensibilité observée dans certains tableaux persistants.','eu83-sensibilisation')
t+=p('La relation peut fonctionner dans les deux directions : une source périphérique contribue à la sensibilisation, et une sensibilisation centrale peut faciliter l’activité des points gâchettes. La persistance ne se résume donc pas forcément au facteur qui a déclenché la première douleur.','eu83-nociplastic')
t+=p('Des effets du needling ont été rapportés sur des régions impliquées dans le traitement sensorimoteur et dans la modulation de la douleur. Ces résultats mécanistiques soutiennent une approche intégrée ; ils ne remplacent pas la mesure des bénéfices fonctionnels du traitement.','eu83-brainstem','eu83-multimodal')
t+=h('3.d — Les adaptations motrices relient douleur, protection et fonction')
t+=p('Les points gâchettes ont été associés à des modifications du recrutement musculaire, à une fatigabilité plus rapide et à une coactivation antagoniste accrue. Le retentissement concerne donc aussi la coordination et la fonction motrice.','eu83-moteur')
t+=p('Une contraction douloureuse favorise parfois la sous-utilisation du muscle atteint. Les muscles voisins peuvent alors compenser davantage, ce qui contribue à des tableaux régionaux plus complexes et à la sensation de faiblesse.','c83-15','c83-16')
t+=p('Ces adaptations justifient un examen du geste et des activités, en complément de la palpation. La réponse recherchée à la rééducation comprend ainsi une amélioration de l’usage du muscle et de la participation aux tâches habituelles.','eu83-moteur','eu83-multimodal')
t+=h('3.e — Corrélation entre mécanisme, exploration et moyen thérapeutique')
rows=[
[p('Une contrainte prolongée ou une surcharge précède le début des symptômes.','c83-17','c83-19'),p('L’entretien décrit la tâche, la posture maintenue et la chronologie.','dgn83-localisation','c83-19'),p('L’adaptation de l’activité et la rééducation cherchent à modifier les contraintes et à restaurer la fonction.','c83-22','eu83-multimodal')],
[p('La bande tendue contient une zone hypersensible.','p83-myofascial-fibro'),p('La palpation localise le point et recherche les symptômes reproduits.','c83-7','iasp83-criteres'),p('Les techniques manuelles ou le dry needling peuvent agir sur la douleur à court terme, dans un programme multimodal.','iasp83-traitement','eu83-multimodal')],
[p('Les médiateurs locaux contribuent aux modèles de sensibilisation périphérique.','eu83-milieu'),p('Le clinicien caractérise la sensibilité à la pression et la douleur référée ; le diagnostic reste clinique.','iasp83-criteres','p83-myofascial-fibro'),p('Une diminution des entrées nociceptives est l’un des mécanismes proposés des interventions locales.','eu83-peripherie')],
[p('La sensibilisation centrale peut entretenir une hypersensibilité durable.','eu83-sensibilisation','eu83-nociplastic'),p('Le bilan porte aussi sur l’étendue des symptômes et leur retentissement sur la vie.','dgn83-localisation','nice83-vie'),p('L’éducation, l’exercice gradué et les stratégies d’autogestion complètent les moyens passifs.','eu83-multimodal')],
[p('La douleur modifie parfois l’activation et la coordination musculaires.','eu83-moteur'),p('L’examen compare la force et la fonction, puis observe les activités limitées.','oa82-hug-force','nice83-vie'),p('L’exercice est adapté aux capacités ; la progression vise une activité plus autonome.','nice83-physique','eu83-multimodal')],
[p('Les attentes et les expériences antérieures influencent le vécu d’un traitement.','eu83-attentes'),p('L’entretien recherche les craintes et les réactions aux soins précédents.','eu83-attentes','nice83-evaluation'),p('Une communication cohérente et un consentement informé accompagnent les choix thérapeutiques.','eu83-communication','dvs83-consentement')]]
t+=table(['Perturbation ou facteur','Exploration clinique','Moyen relié au mécanisme'],rows)
t+=p('La réponse immédiate à une technique locale et l’évolution fonctionnelle à distance sont deux observations différentes. Les bénéfices surtout courts des techniques passives justifient donc d’intégrer des moyens actifs et un suivi adapté.','eu83-limite-effet','eu83-multimodal')
save(t)
